import {compareInsert,comparePresets,cascadeFamily,treeFromSequence,countNodes} from './rb-compare-engine.js';
import {parseRBKeys} from './redblack-lab-engine.js';
import {esc,rbTreeSVG} from './redblack-lab-view.js';
const $=s=>document.querySelector(s);
function searchPath(n,k){const a=[];while(!n.nil){a.push(n.id);if(n.key===k)break;n=k<n.key?n.left:n.right}return a}
export function compareSVG(root,focus=[],compact=true){if(!compact)return rbTreeSVG(root,{roles:focus[0]?{X:focus[0]}:{},title:'完整红黑树'});const keep=new Set(focus);function marked(n){return !n.nil&&(keep.has(n.id)||marked(n.left)||marked(n.right))}const ps=[],edges=[];let x=0,maxd=0;function visit(n,d=0){if(n.nil)return null;const folded=countNodes(n)>2&&!marked(n),l=folded?null:visit(n.left,d+1),p={n,folded,x:55+95*x++,y:52+d*105};ps.push(p);const r=folded?null:visit(n.right,d+1);if(l)edges.push([p,l]);if(r)edges.push([p,r]);maxd=Math.max(maxd,d);return p}visit(root);const w=Math.max(350,110+95*Math.max(0,x-1)),h=Math.max(180,160+105*maxd);return `<svg xmlns="http://www.w3.org/2000/svg" class="rbc-svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" role="img" aria-label="红黑树路径聚焦图"><title>圆点为实际节点；三角形折叠整棵旁支，标签含根颜色与完整节点数</title><g font-family="Microsoft YaHei,sans-serif" text-anchor="middle">${edges.map(([a,b])=>`<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#9caaa2" stroke-width="2"/>`).join('')}${ps.map(({n,x,y,folded})=>`<g data-rbc-node="${n.id}" transform="translate(${x} ${y})">${folded?`<path d="M0,-27 L-40,29 L40,29 Z" fill="${n.color==='R'?'#f1d3ce':'#e1e8e8'}" stroke="${n.color==='R'?'#b3473b':'#3c565b'}"/><text y="15" font-size="12" fill="#233f37">根 ${n.key} ${n.color}</text><text y="49" font-size="11" fill="#687a6b">共 ${countNodes(n)} 节点</text>`:`<circle r="24" fill="${n.color==='R'?'#b74640':'#293f49'}" stroke="${keep.has(n.id)?'#d8a449':'#fff'}" stroke-width="${keep.has(n.id)?3:1}"/><text y="6" font-size="16" fill="white">${n.key}</text><text x="22" y="-22" font-size="12" fill="${n.color==='R'?'#a53730':'#29424a'}" stroke="#fafbf8" stroke-width="3" paint-order="stroke">${n.color}</text>`}</g>`).join('')}${!ps.length?'<text x="175" y="80">空树 · NIL 黑</text>':''}</g></svg>`}
export const compareReading=`<h2>比较的是哪两种算法？</h2><p><b>Bottom-up：</b>先按普通 BST 搜索并挂入红叶，再按红父/红叔规则向上修复；叔红时向上变色，叔黑时至多两旋收尾。<b>Top-down：</b>采用 Weiss 风格的对称红黑插入：下降到节点时，若两个孩子都红，就预先分裂这个 4-node；若分裂引发红红冲突，立即作局部旋转，再继续下降。这里没有强制红链接左倾，也没有把 LLRB 混入比较。</p><p>初始树只建一次，再连同颜色完整复制。除“极端族”直接按规则构造合法树外，初始序列统一用 Bottom-up 建树。不是分别让两种算法自行建树后才开始比较。多键自定义序列从共同状态开始，此后允许两边分化。</p>
<div class="rbc-table"><table><thead><tr><th>关注点</th><th>Bottom-up</th><th>Top-down（本页版本）</th></tr></thead><tbody><tr><td>何时拆满 4-node</td><td>新键引发冲突，向上修复时</td><td>下降途中遇到就拆</td></tr><tr><td>挂入新键之前</td><td>搜索不修改原树</td><td>已经可能变色和旋转</td></tr><tr><td>父黑的新红叶</td><td>立即完成，不再修复</td><td>末尾不用修，但沿途操作已发生</td></tr><tr><td>回溯</td><td>可经父指针或祖先栈向上</td><td>没有末尾回溯循环，保留常数个祖先即可</td></tr><tr><td>单次时间</td><td>最坏 O(log n)</td><td>最坏 O(log n)</td></tr><tr><td>旋转</td><td>经典插入至多 2 次</td><td>可在下降的不同位置修复，不能套用左列证明</td></tr><tr><td>最终树</td><td colspan="2">键集合相同；合法树的形状与颜色不唯一</td></tr></tbody></table></div>
<h3>主例：Bottom-up 没事，Top-down 为什么反而旋转？</h3><p>17 节点主例把 110 插在黑节点 100 下。Bottom-up 只新增红叶即可。Top-down 在到达插入位置前遇到黑节点 80 的两个红孩子，先把 80 变红、孩子变黑；80 的父亲此时也红，于是先拉直折线，再换色旋转祖父。这两个旋转都发生在新键 110 挂入之前。最终两边都合法，但连形状也不同。</p>
<h3>可扩展的极端族：0 次修复，对照 Θ(log n) 次预处理</h3><p>令 T₀ 是一个黑色单节点，Bₕ 是 h 层全黑完美二叉树（B₀=NIL）。Tₕ 的黑根有两个红孩子；左红孩子的左子树为 Tₕ₋₁，其余三棵子树均为 Bₕ。按中序赋键 10,20,…，插入 0。</p><div class="rbc-formula">T(h) = 黑根 [ 红(T(h−1), B(h)), 红(B(h), B(h)) ]<br>n(h) = n(h−1) + 3 + 3(2^h−1) = 6·2^h − 5，n(0)=1</div>
<p>有效性可归纳验证：Tₕ₋₁ 与 Bₕ 从自身根到 NIL 的黑数均为 h+1，故两个红孩子的两侧等黑；再加上黑根得到 h+2。红节点的孩子全黑，所以没有红红冲突。</p><p>最左路径遇到 h 个满 4-node，但最后的叶父仍为黑。Bottom-up 挂入红 0 后直接结束：0 分裂、0 旋转、0 次已有节点颜色变化。Top-down 逐层分裂：h 次分裂、0 次旋转，颜色变化为 3h+1 次（h≥1）。根的“黑→红→黑”计两次实际变化，故根层共 4 次，其他层各 3 次。</p><p>h=1、2、3、4 时分别有 7、19、43、91 个初始节点；Top-down 颜色变化为 4、7、10、13 次。h=Θ(log n)，所以这是一族可增长的差异。此例两边形状相同、颜色不同；要看形状差异，请选 17 节点主例。三角形仅折叠旁支显示，统计与验证始终使用完整树。</p>
<h3>不能据此宣布谁总是更快</h3><p>Top-down 用预处理换取单趟下降的控制流程；Bottom-up 把修复推迟到确有冲突之后。两者都是对数时间。这里展示某些输入上的结构操作差异，未测量缓存、分支预测或分配成本，也没有证明一种实现对全部序列更优。</p><p>统计口径：每次旋转计 1；分裂指一次“黑父两红子 → 红父两黑子”的成组处理；颜色变化只统计 R↔B，根变回黑也计入；新节点初始染红不算变色。下降停靠数是教学事件数，不是精确比较指令数。快照与画图不纳入算法成本。实现使用父指针方便统一表示，但 Top-down 不沿父指针执行最终回溯。</p>
<h3>重复键是一个有用的追问</h3><p>本 Top-down 实现先检查分裂，再比较相等。因此即使最后发现键已经存在，集合不变，树形/颜色仍可能调整。Bottom-up 在只读搜索中发现重复键就返回。若接口要求失败插入绝不改结构，可预先查找，但会多一趟搜索，属于另一种接口策略。</p><p>Top-down 规则见 <a href="https://users.cis.fiu.edu/~weiss/dsaajava/code/DataStructures/RedBlackTree.java" target="_blank" rel="noopener">Weiss 的原始实现</a>；Bottom-up 见 <a href="https://www.cs.dartmouth.edu/~thc/cs10/lectures/0519/0519.html" target="_blank" rel="noopener">Cormen 的课程讲义</a>。极端族、计数实验与并排可视化为本课程编写。</p>`;
export function mountRBCompare(){let result,selected='rotations',stage=0,timer=null,compact=true,actual=false,positions=[0,0];document.title='Top-down vs Bottom-up 红黑树插入 · ADS';$('#breadcrumb').textContent='第二课 / 红黑树插入对比';document.querySelectorAll('[data-chapter]').forEach(a=>a.classList.toggle('active',a.dataset.chapter==='btrees'));
 $('#main').innerHTML=`<article class="rbc-page"><div class="eyebrow">CHAPTER 02 / SAME INPUT, DIFFERENT TIMING</div><h1>先修路，还是插完再修？<span class="rb-subtitle">Top-down 与 Bottom-up 红黑树插入对比</span></h1><p class="intro">同一棵初始树，同一个插入键。观察“新键还没进树时，算法已经做了什么”。</p><div class="rb-links"><a href="#btrees/redblack-lab">红黑树基础图解 ↗</a><button id="rbc-insert-moment">跳到刚挂入新键</button><button id="rbc-end">比较最终结果</button><button id="rbc-export">下载当前对比 SVG</button></div><div class="rb-toolbar"><label class="rb-wide">案例<select id="rbc-preset">${comparePresets.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label id="rbc-level-wrap" hidden>极端族层数 h<select id="rbc-level"><option>1</option><option>2</option><option selected>3</option><option>4</option></select></label></div><p class="rb-note" id="rbc-why"></p><details><summary>修改初始插入序列与待插入键</summary><div class="rb-toolbar"><label class="rb-wide">初始序列（生成共同初始树）<input id="rbc-initial"></label><label class="rb-wide">待插入序列（允许重复）<input id="rbc-keys"></label><button id="rbc-run">重新比较</button></div><p>初始序列最多 24 个互异键。极端族使用定义好的合法树，初始序列框禁用；可以修改层数与待插入键。</p></details><p role="alert" id="rbc-error"></p><div class="rb-player"><button id="rbc-first">↺</button><button id="rbc-prev" aria-label="对比上一步">◀</button><button id="rbc-play" class="primary">▶ 同步播放</button><button id="rbc-next" aria-label="对比下一步">▶|</button><input id="rbc-seek" type="range" min="0" value="0" aria-label="对比步骤"></div><p class="rbc-caption">同步步按各自事件序号推进，先结束的一侧停在终态；它不是相同 CPU 时间。“刚挂入新键”按语义事件对齐两边。</p><div class="rb-links"><button id="rbc-compact" aria-pressed="true">展开完整树</button><button id="rbc-size" aria-pressed="false">原始字号</button></div><div id="rbc-summary"></div><div id="rbc-panels"></div><div class="rbc-reading">${compareReading}</div></article>`;
 const stop=()=>{clearInterval(timer);timer=null;if($('#rbc-play'))$('#rbc-play').textContent='▶ 同步播放'};
 function panel(fs,pos,name){const f=fs[pos],focus=[...new Set([...result.keys.flatMap(k=>searchPath(f.root,k)),...f.focus])];return `<section class="rbc-panel"><h2>${name}</h2><div class="rbc-frame"><small>事件 ${pos+1}/${fs.length} · 第 ${f.operation} 次插入</small><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p><b class="rbc-badge ${f.inserted?'added':''}">${f.inserted?'当前键已挂入':'当前操作尚未新增节点'}</b></div><div class="rbc-metrics">${[['旋转',f.stats.rotations],['分裂',f.stats.splits],['颜色变化',f.stats.recolors],['下降停靠',f.stats.visits]].map(([k,v])=>`<span>${k}<b>${v}</b></span>`).join('')}</div><div class="rb-scroll">${compareSVG(f.root,focus,compact)}</div><div class="rbc-local"><button data-rbc-prev="${name==='Bottom-up'?0:1}" ${pos===0?'disabled':''}>此侧上一步</button><button data-rbc-next="${name==='Bottom-up'?0:1}" ${pos===fs.length-1?'disabled':''}>此侧下一步</button></div><details><summary>事件时间线与路径黑数</summary><p>当前实际路径黑数：${[...new Set(f.paths.map(p=>p.black))].join(' / ')}。修复中间帧可暂时出现红红；完成帧必须恢复全部性质。</p><ol>${fs.map((x,i)=>`<li class="${i===pos?'active':''}">${esc(x.title)} ${x.inserted?'[已挂入]':''}</li>`).join('')}</ol></details></section>`}
 function paint(){const bothEnd=positions[0]===result.bottom.length-1&&positions[1]===result.top.length-1;$('#rbc-summary').innerHTML=`<div class="rbc-result"><b>${countNodes(result.initial)} 个初始节点 · 插入 ${result.keys.join(', ')}</b><span>${bothEnd?(result.sameFinal?'最终结构与颜色相同；比较处理顺序。':'最终颜色或结构不同，但两边都满足红黑性质。'):'先观察：哪一侧在新节点挂入之前就已变色或旋转？'}</span></div>`;$('#rbc-panels').className='rbc-panels'+(actual?' rbc-actual':'');$('#rbc-panels').innerHTML=panel(result.bottom,positions[0],'Bottom-up')+panel(result.top,positions[1],'Top-down');$('#rbc-prev').disabled=positions.every(i=>i===0);$('#rbc-next').disabled=bothEnd;$('#rbc-seek').value=stage;document.querySelectorAll('[data-rbc-prev],[data-rbc-next]').forEach(b=>b.onclick=()=>{stop();const which=+(b.dataset.rbcPrev??b.dataset.rbcNext);positions[which]+=b.dataset.rbcNext!==undefined?1:-1;paint()})}
 function sync(i){stage=i;positions=[Math.min(i,result.bottom.length-1),Math.min(i,result.top.length-1)];paint()}
 function run(){stop();try{const p=comparePresets.find(p=>p.id===selected),root=p.kind==='family'?cascadeFamily(+$('#rbc-level').value):treeFromSequence(parseRBKeys($('#rbc-initial').value)),raw=$('#rbc-keys').value.trim();if(!raw)throw Error('请输入待插入键');result=compareInsert(root,raw.split(/[,，\s]+/).map(Number));$('#rbc-error').textContent='';$('#rbc-seek').max=Math.max(result.bottom.length,result.top.length)-1;sync(0)}catch(e){$('#rbc-error').textContent=e.message+'；保留上次有效对比。'}}
 function choose(id){selected=id;const p=comparePresets.find(p=>p.id===id);$('#rbc-why').textContent=p.why;$('#rbc-level-wrap').hidden=p.kind!=='family';$('#rbc-level').value=p.level||3;$('#rbc-initial').disabled=p.kind==='family';$('#rbc-initial').value=p.initial||'';$('#rbc-initial').placeholder=p.kind==='family'?'按正文定义直接构造合法树':'';$('#rbc-keys').value=p.insert;run()}
 $('#rbc-preset').onchange=e=>choose(e.target.value);$('#rbc-level').onchange=run;$('#rbc-run').onclick=run;$('#rbc-first').onclick=()=>{stop();sync(0)};$('#rbc-prev').onclick=()=>{stop();sync(Math.max(0,Math.min(...positions)-1))};$('#rbc-next').onclick=()=>{stop();sync(Math.min(+$('#rbc-seek').max,Math.max(...positions)+1))};$('#rbc-seek').oninput=e=>{stop();sync(+e.target.value)};$('#rbc-end').onclick=()=>{stop();sync(+$('#rbc-seek').max)};
 $('#rbc-insert-moment').onclick=()=>{stop();positions=[result.bottom,result.top].map(fs=>{const i=fs.findIndex(f=>f.type==='insert');return i<0?fs.length-1:i});stage=Math.max(...positions);paint()};$('#rbc-play').onclick=()=>{if(timer){stop();return}if(positions[0]===result.bottom.length-1&&positions[1]===result.top.length-1)sync(0);stage=Math.max(...positions);$('#rbc-play').textContent='Ⅱ 暂停';timer=setInterval(()=>{sync(stage+1);if(stage>=+$('#rbc-seek').max)stop()},1200)};
 $('#rbc-compact').onclick=()=>{compact=!compact;$('#rbc-compact').setAttribute('aria-pressed',String(compact));$('#rbc-compact').textContent=compact?'展开完整树':'聚焦插入路径';paint()};$('#rbc-size').onclick=()=>{actual=!actual;$('#rbc-size').setAttribute('aria-pressed',String(actual));$('#rbc-size').textContent=actual?'适应画布':'原始字号';paint()};
 $('#rbc-export').onclick=()=>{const fs=[result.bottom[positions[0]],result.top[positions[1]]],svgs=fs.map(f=>compareSVG(f.root,[...f.focus,...result.keys.flatMap(k=>searchPath(f.root,k))],compact)),widths=svgs.map(s=>+s.match(/width="(\d+)"/)[1]),height=180+Math.max(...svgs.map(s=>+s.match(/height="(\d+)"/)[1])),width=widths[0]+widths[1]+40;const text=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><rect width="100%" height="100%" fill="#fafbf8"/><g font-family="sans-serif" fill="#294339"><text x="20" y="30" font-size="22">Red-black insertion: ${result.keys.join(', ')} · Bottom-up / Top-down</text>${fs.map((f,i)=>`<g transform="translate(${i?widths[0]+40:0},55)"><text x="15" y="22" font-size="20">${i?'Top-down':'Bottom-up'}</text><text x="15" y="48" font-size="14">rotate=${f.stats.rotations} split=${f.stats.splits} recolor=${f.stats.recolors}</text>${svgs[i].replace('<svg ','<svg x="0" y="65" ')}</g>`).join('')}</g></svg>`;const url=URL.createObjectURL(new Blob([text],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download='ADS-redblack-top-bottom.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};choose(selected);return stop;
}
